namespace Relay.Api.Tests;

public sealed class ThrowawayInputTests
{
    [Theory]
    [InlineData("/api/accounts/6/activity-health?type=")]
    [InlineData("/api/accounts/6/activity-health?type=ALL")]
    [InlineData("/api/accounts/6/activity-health?type=%20all")]
    [InlineData("/api/accounts/6/activity-health?week=abc")]
    [InlineData("/api/accounts/6/activity-health?week=")]
    public async Task ShapeErrorsAreBadRequestProblems(string path)
    {
        await using var factory = new WebApplicationFactory<Program>();
        using var client = factory.CreateClient();

        using var response = await client.GetAsync(new Uri(path, UriKind.Relative), TestContext.Current.CancellationToken);
        var body = await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken);
        TestContext.Current.TestOutputHelper?.WriteLine($"{path} -> {(int)response.StatusCode} {response.Content.Headers.ContentType} {body}");

        response.StatusCode.ShouldBe(HttpStatusCode.BadRequest, body);
        response.Content.Headers.ContentType?.MediaType.ShouldBe("application/problem+json", body);
    }
}

