using System.Net;
using Microsoft.AspNetCore.Mvc.Testing;

namespace Relay.Api.Tests;

public sealed class ThrowawayWeekTests
{
    [Theory]
    [InlineData("week=abc")]
    [InlineData("week=2026-13-01")]
    [InlineData("week=20260720")]
    [InlineData("week=")]
    [InlineData("week=07/20/2026")]
    [InlineData("week=2026-7-20")]
    [InlineData("type=")]
    [InlineData("type=ALL")]
    public async Task MalformedInputIsBadRequestProblem(string queryString)
    {
        await using var factory = new WebApplicationFactory<Program>();
        using var client = factory.CreateClient();

        using var response = await client.GetAsync(new Uri($"/api/accounts/6/activity-health?{queryString}", UriKind.Relative), TestContext.Current.CancellationToken);
        var body = await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken);
        TestContext.Current.TestOutputHelper?.WriteLine($"{queryString} -> {(int)response.StatusCode} {response.Content.Headers.ContentType?.MediaType} {body}");

        response.StatusCode.ShouldBe(HttpStatusCode.BadRequest, body);
        response.Content.Headers.ContentType?.MediaType.ShouldBe("application/problem+json", body);
    }
}

